  }

  const updates = buildBreakingNewsUpdatesFromEvent(mostRecentEvent);
  return {
    ...homepageBreakingNews,
    main: buildBreakingNewsMainFromEvent(mostRecentEvent),
    updates: updates.length > 0 ? updates : []
  };
}

